import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from beeswarm ----
/** mulberry32, seeded so the swarm is byte-identical on every reload. */
function createRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const MAKES = ['Alcyone', 'Bellwether', 'Corvid', 'Dunlin', 'Eider', 'Fulmar', 'Godwit', 'Harrier'];

/** Three modes, so the swarm visibly thickens and thins across the axis. */
const MODES: { count: number; mean: number; spread: number }[] = [
  { count: 150, mean: 2350, spread: 240 },
  { count: 120, mean: 3350, spread: 290 },
  { count: 70, mean: 4300, spread: 360 }
];

type Vehicle = { name: string; weight: number };

function createVehicles(seed: number): Vehicle[] {
  const random = createRandom(seed);
  const vehicles: Vehicle[] = [];
  for (const { count, mean, spread } of MODES) {
    for (let i = 0; i < count; i++) {
      const u = random() || Number.EPSILON; // Box-Muller diverges at exactly zero
      const normal = Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * random());
      const index = vehicles.length;
      vehicles.push({
        name: `${MAKES[index % MAKES.length]} ${300 + index}`,
        weight: Math.round((mean + spread * normal) / 10) * 10
      });
    }
  }
  return vehicles;
}

const vehicleWeights: Vehicle[] = createVehicles(20260813);

const MARGIN = { top: 16, right: 20, bottom: 36, left: 20 };

/** One named observation per dot, positioned along the axis by its value. */
export type Data = { name: string; weight: number }[];

/** Swarm depth grows with dot area and shrinks with span, so tie the dot to the span. */
const dotRadius = (innerWidth: number) => Math.min(5.5, Math.max(1.5, innerWidth / 225));

type Placed = { vehicle: Data[number]; x: number; y: number };

/**
 * One-sided dodge: walk the points in x order and stack each on the smallest y >= 0
 * that clears every already-placed circle still within one diameter. Unlike the
 * mirrored variant, ties always resolve upward off a single baseline.
 */
function dodge(points: { vehicle: Data[number]; x: number }[], diameter: number): Placed[] {
  const diameter2 = diameter ** 2;
  const epsilon = 1e-3;
  const sorted = [...points].sort((a, b) => a.x - b.x);
  const placed: Placed[] = [];
  let head = 0; // placed is x-sorted, so live neighbours are the suffix from here

  const intersects = (x: number, y: number) => {
    for (let i = head; i < placed.length; i++) {
      const a = placed[i];
      if (diameter2 - epsilon > (a.x - x) ** 2 + (a.y - y) ** 2) return true;
    }
    return false;
  };

  for (const point of sorted) {
    while (head < placed.length && placed[head].x < point.x - diameter) head++;

    let y = 0;
    if (intersects(point.x, 0)) {
      y = Infinity;
      for (let i = head; i < placed.length; i++) {
        const a = placed[i];
        const gap = diameter2 - (a.x - point.x) ** 2;
        if (gap < 0) continue;
        const candidate = a.y + Math.sqrt(gap);
        if (candidate < y && !intersects(point.x, candidate)) y = candidate;
      }
      if (!Number.isFinite(y)) y = diameter; // no tangent cleared: stack rather than emit Infinity
    }
    placed.push({ vehicle: point.vehicle, x: point.x, y });
  }

  return placed;
}

export default function Beeswarm({ data = vehicleWeights, width }:
  { data?: Data; width: number }) {
  // Margins are fixed, so scale the plot band itself rather than the outer height.
  const innerHeight = Math.round(width * 0.24);
  const height = innerHeight + MARGIN.top + MARGIN.bottom;
  const innerWidth = width - MARGIN.left - MARGIN.right;

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([
          d3.min(data, (d) => d.weight) ?? 0,
          d3.max(data, (d) => d.weight) ?? 0
        ])
        .nice()
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const radius = dotRadius(innerWidth);

  const swarm = useMemo(
    () =>
      dodge(
        data.map((vehicle) => ({ vehicle, x: x(vehicle.weight) })),
        radius * 2.375 // one diameter plus a padding that scales with the dot
      ),
    [data, x, radius]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(8).map((v) => ({ value: d3.format(',')(v), offset: x(v) })),
    [x]
  );

  if (width === 0) return null;

  const baseline = innerHeight - radius;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Beeswarm of vehicle curb weight, one dot per vehicle"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {swarm.map((d) => (
          <circle
            key={d.vehicle.name}
            cx={d.x}
            cy={baseline - d.y}
            r={radius}
            fill="var(--accent)"
            fillOpacity={0.85}
            stroke="var(--bg)"
            strokeWidth={0.75}
          >
            <title>{`${d.vehicle.name}, ${d3.format(',')(d.vehicle.weight)} lb`}</title>
          </circle>
        ))}
      </g>
    </svg>
  );
}
